CREATE TABLE workspaces (id VARCHAR(36) PRIMARY KEY, name VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(12) NOT NULL DEFAULT 'OWNER');
CREATE TABLE subscriptions (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name VARCHAR(100) NOT NULL, category VARCHAR(80) NOT NULL, owner VARCHAR(100) NOT NULL, owner_email VARCHAR(254) NOT NULL DEFAULT '', cycle VARCHAR(10) NOT NULL CHECK(cycle IN ('Monthly','Yearly')), amount_minor BIGINT NOT NULL CHECK(amount_minor > 0), next_renewal DATE NOT NULL, last_used DATE, active BOOLEAN NOT NULL DEFAULT TRUE, reviewed BOOLEAN NOT NULL DEFAULT TRUE, capabilities VARCHAR(1000) NOT NULL DEFAULT '', notes VARCHAR(4000) NOT NULL DEFAULT '', pulse_answer VARCHAR(3), source VARCHAR(20) NOT NULL DEFAULT 'MANUAL', version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX subscriptions_workspace ON subscriptions(workspace_id);
CREATE TABLE charges (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, subscription_id VARCHAR(36) NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, amount_minor BIGINT NOT NULL, charged_on DATE NOT NULL, source_ref VARCHAR(100));
CREATE UNIQUE INDEX charges_source ON charges(workspace_id,source_ref);
CREATE TABLE domains (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, fqdn VARCHAR(253) NOT NULL, registrar VARCHAR(100) NOT NULL DEFAULT '', expires_on DATE NOT NULL, auto_renew BOOLEAN NOT NULL DEFAULT FALSE, source VARCHAR(20) NOT NULL DEFAULT 'MANUAL', last_checked_at TIMESTAMP, UNIQUE(workspace_id,fqdn));
CREATE TABLE usage_pulses (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, subscription_id VARCHAR(36) NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, sent_to VARCHAR(254) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, expires_on DATE NOT NULL, answered_at TIMESTAMP, answer VARCHAR(3));
CREATE TABLE reports (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, created_on DATE NOT NULL, input_snapshot TEXT NOT NULL, output_text TEXT NOT NULL, model VARCHAR(100) NOT NULL);
CREATE TABLE notifications (id VARCHAR(36) PRIMARY KEY, workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, target_id VARCHAR(36) NOT NULL, kind VARCHAR(20) NOT NULL, due_on DATE NOT NULL, recipient VARCHAR(254) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at TIMESTAMP, last_error VARCHAR(500), UNIQUE(target_id,kind,due_on));
CREATE INDEX notifications_pending ON notifications(status,next_attempt_at);
CREATE TABLE import_runs (workspace_id VARCHAR(36) NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, file_hash VARCHAR(64) NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(workspace_id,file_hash));
CREATE TABLE job_runs (id VARCHAR(36) PRIMARY KEY, job_name VARCHAR(80) NOT NULL, started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TIMESTAMP, status VARCHAR(20) NOT NULL);
